/// <summary>
/// Who inside the program may see a record. Part 2 permits communications within a program to personnel who need
/// the information for treatment (§2.12(c)(3)); that need-to-know is expressed as clinical roles.
/// Counseling notes stay with their author, like HIPAA psychotherapy notes.
/// </summary>
internal static class ReadPolicy
{
    /// <param name="emergency">True when the actor holds emergency access to this record's resident right now.</param>
    public static AccessDecision Decide(ICurrentUser actor, RecordDescriptor record, bool emergency = false)
    {
        ArgumentNullException.ThrowIfNull(actor);
        ArgumentNullException.ThrowIfNull(record);

        if (!actor.Scope.AllowsClient(record.ClientId))
        {
            return AccessDecision.Deny("This resident is outside your assigned facilities.");
        }

        // Emergency access opens what clinical staff see, to a person, for a resident, for a reason on record.
        // It does not open counseling notes and it is never an agent's.
